"""Default and user-defined exclusions: dependencies, build output, binaries, generated files,
lockfiles (IDX-05)."""

from pathlib import PurePosixPath

import pathspec

EXCLUDED_DIRS = frozenset(
    {
        ".git", ".hg", ".svn",
        "node_modules", "bower_components", "vendor",
        "dist", "build", "out", "target", "bin", "obj",
        ".gradle", ".idea", ".vscode", ".vs",
        "__pycache__", ".venv", "venv", ".tox",
        ".mypy_cache", ".pytest_cache", ".ruff_cache",
        ".next", ".nuxt", ".angular", ".svelte-kit",
        "coverage", ".terraform", "Pods", ".dart_tool",
    }
)  # fmt: skip

LOCKFILES = frozenset(
    {
        "package-lock.json", "yarn.lock", "pnpm-lock.yaml", "bun.lockb",
        "poetry.lock", "uv.lock", "Pipfile.lock", "pdm.lock",
        "Cargo.lock", "composer.lock", "Gemfile.lock", "go.sum",
        "packages.lock.json", "gradle.lockfile", "mix.lock", "pubspec.lock",
    }
)  # fmt: skip

BINARY_SUFFIXES = frozenset(
    {
        ".png", ".jpg", ".jpeg", ".gif", ".ico", ".bmp", ".webp", ".svg", ".tiff",
        ".pdf", ".zip", ".tar", ".gz", ".tgz", ".bz2", ".xz", ".7z", ".rar",
        ".jar", ".war", ".ear", ".class", ".dll", ".exe", ".so", ".dylib", ".o", ".a",
        ".lib", ".pdb", ".pyc", ".pyo", ".nupkg",
        ".woff", ".woff2", ".ttf", ".otf", ".eot",
        ".mp3", ".mp4", ".mov", ".avi", ".wav", ".ogg",
        ".db", ".sqlite", ".sqlite3", ".bin", ".dat",
    }
)  # fmt: skip

GENERATED_SUFFIXES = (
    ".min.js", ".min.css", ".map", ".designer.cs", ".g.cs", ".g.i.cs",
    "_pb2.py", "_pb2_grpc.py", ".pb.go",
)  # fmt: skip

GENERATED_MARKERS = (b"@generated", b"Code generated", b"DO NOT EDIT", b"<auto-generated")


class Exclusions:
    """Decides what the indexer skips. User patterns are gitignore-style, relative to the Root."""

    def __init__(self, patterns: list[str] | None = None) -> None:
        self._spec = pathspec.GitIgnoreSpec.from_lines(patterns or [])

    def dir_excluded(self, root_relative: PurePosixPath) -> str | None:
        if root_relative.name in EXCLUDED_DIRS:
            return f"excluded directory: {root_relative.name}"
        if self._spec.match_file(f"{root_relative.as_posix()}/"):
            return "excluded by stc.toml"
        return None

    def file_excluded(self, root_relative: PurePosixPath) -> str | None:
        name = root_relative.name
        lowered = name.lower()
        if name in LOCKFILES:
            return "lockfile"
        if lowered.endswith(GENERATED_SUFFIXES):
            return "generated file"
        if root_relative.suffix.lower() in BINARY_SUFFIXES:
            return "binary or asset"
        if self._spec.match_file(root_relative.as_posix()):
            return "excluded by stc.toml"
        return None

    @staticmethod
    def looks_generated(head: bytes) -> bool:
        return any(marker in head for marker in GENERATED_MARKERS)
